import{_ as t,o,c as d,a5 as a}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Plan — FR 3.2.6: OTP Verification","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/01-authentication/3-2-6-otp-verification/plan.md","filePath":"feature/srs/01-authentication/3-2-6-otp-verification/plan.md"}'),c={name:"feature/srs/01-authentication/3-2-6-otp-verification/plan.md"};function n(r,e,i,s,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="plan-—-fr-3-2-6-otp-verification" tabindex="-1">Plan — FR 3.2.6: OTP Verification <a class="header-anchor" href="#plan-—-fr-3-2-6-otp-verification" aria-label="Permalink to &quot;Plan — FR 3.2.6: OTP Verification&quot;">​</a></h1><p>&gt; Implements <a href="./spec.html">spec.md</a> — Dual purpose-scoped 6-digit OTP verification flows: Guest Sign-Up Email OTP (<code>verify-otp</code> / <code>resend-otp</code>) and Authenticated Phone-Link OTP (<code>link/phone</code> / <code>verify-phone-otp</code>), enforcing 10-minute TTL (<code>BR-03</code>), 5-strike invalidation, and 60-second resend cooldown (<code>BR-04</code>).</p><h2 id="_1-technical-component-map" tabindex="-1">1. Technical Component Map <a class="header-anchor" href="#_1-technical-component-map" aria-label="Permalink to &quot;1. Technical Component Map&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Layer</th><th style="text-align:left;">Repository / Package</th><th style="text-align:left;">Concrete Classes &amp; Files</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>API Gateway</strong></td><td style="text-align:left;"><code>brandhub-api-gateway</code></td><td style="text-align:left;"><code>GatewayConfig.java</code> (public <code>/verify-otp</code>, <code>/resend-otp</code>; JWT-protected <code>/link/phone</code>, <code>/verify-phone-otp</code>)</td></tr><tr><td style="text-align:left;"><strong>Controller</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>controller/auth/AuthController.java</code> (<code>verifyOtp</code>, <code>resendOtp</code>, <code>linkPhone</code>, <code>verifyPhoneOtp</code>, <code>unlinkPhone</code>)</td></tr><tr><td style="text-align:left;"><strong>Service</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>service/impl/auth/AuthServiceImpl.java</code>, <code>service/mail/MailService.java</code> (<code>sendOtpEmail</code>)</td></tr><tr><td style="text-align:left;"><strong>DTOs &amp; Errors</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>VerifyOtpRequest</code>, <code>ForgotPasswordRequest</code>, <code>LinkPhoneRequest</code>, <code>VerifyPhoneOtpRequest</code>, <code>ErrorCode</code> (<code>OTP_INVALID</code>, <code>OTP_TOO_MANY_ATTEMPTS</code>, <code>RATE_LIMIT_EXCEEDED</code>, <code>INVALID_PHONE</code>, <code>PHONE_ALREADY_IN_USE</code>)</td></tr><tr><td style="text-align:left;"><strong>Persistence</strong></td><td style="text-align:left;"><code>brandhub-business-service</code></td><td style="text-align:left;"><code>UserRepository.java</code> (<code>otp_code</code>, <code>otp_expiry</code>, <code>email_verified_at</code>, <code>phone</code>), <code>StringRedisTemplate</code></td></tr><tr><td style="text-align:left;"><strong>Web Frontend</strong></td><td style="text-align:left;"><code>brandhub-web</code></td><td style="text-align:left;"><code>src/pages/auth/VerifyOtpPage.tsx</code>, <code>src/pages/profile/components/LinkPhoneModal.tsx</code>, <code>src/services/authService.ts</code></td></tr><tr><td style="text-align:left;"><strong>Mobile App</strong></td><td style="text-align:left;"><code>brandhub-mobile-app</code></td><td style="text-align:left;"><code>app/(auth)/verify-otp.tsx</code>, <code>src/screens/settings/AccountSettingsScreen.tsx</code></td></tr></tbody></table><h2 id="_2-purpose-scoped-architecture-storage-model" tabindex="-1">2. Purpose-Scoped Architecture &amp; Storage Model <a class="header-anchor" href="#_2-purpose-scoped-architecture-storage-model" aria-label="Permalink to &quot;2. Purpose-Scoped Architecture &amp; Storage Model&quot;">​</a></h2><p>Rather than a generic <code>otpSessionId</code> endpoint, BrandHub isolates OTP flows by security boundary so unauthenticated calls can never touch authenticated mutations:</p><ol><li><strong>Flow A — Sign-Up Email OTP (Public):</strong><ul><li><strong>PostgreSQL <code>users</code>:</strong> Stores <code>otp_code</code> (6 digits) and <code>otp_expiry</code> (10-min TTL); stamps <code>email_verified_at = now</code> and clears OTP columns upon success.</li><li><strong>Redis Keys:</strong> <code>otp:attempt:{email}</code> (TTL 10m, max 5 failed tries) and <code>otp:resend:{email}</code> (TTL 60s cooldown).</li></ul></li><li><strong>Flow B — Phone Link OTP (Bearer Authenticated):</strong><ul><li><strong>Redis Keys:</strong> <code>phone:otp:{userId}</code> storing <code>&quot;&lt;6digitOtp&gt;:&lt;normalizedPhone&gt;&quot;</code> (TTL 10m), <code>phone:otp:attempt:{userId}</code> (TTL 10m, max 5 failed tries), and <code>phone:otp:resend:{userId}</code> (TTL 60s cooldown).</li><li><strong>Delivery Channel:</strong> Dispatched to the user&#39;s verified account email via <code>mailService.sendOtpEmail</code> (confirming account owner consent before binding <code>users.phone</code>).</li><li><strong>PostgreSQL <code>users</code>:</strong> Updates <code>users.phone</code> (<code>UNIQUE</code>) only after re-verifying phone uniqueness at the moment of <code>verifyPhoneOtp</code> to eliminate TOCTOU race conditions.</li></ul></li></ol><h2 id="_3-end-to-end-execution-flow" tabindex="-1">3. End-to-End Execution Flow <a class="header-anchor" href="#_3-end-to-end-execution-flow" aria-label="Permalink to &quot;3. End-to-End Execution Flow&quot;">​</a></h2><ol><li><strong>Email OTP (<code>POST /api/v1/auth/verify-otp</code> &amp; <code>/resend-otp</code>):</strong><ul><li>Normalizes email; returns idempotent <code>200 OK</code> if already verified; checks <code>otpCode</code> &amp; <code>otpExpiry</code>; tracks failures in <code>otp:attempt:{email}</code> (5th failure clears <code>otpCode</code>/<code>otpExpiry</code> and throws <code>400 OTP_TOO_MANY_ATTEMPTS</code>); sets <code>emailVerifiedAt = now</code> on match.</li></ul></li><li><strong>Phone OTP (<code>POST /api/v1/auth/link/phone</code> &amp; <code>/verify-phone-otp</code>):</strong><ul><li><code>linkPhone</code>: validates phone format (<code>400 INVALID_PHONE</code>), checks <code>userRepository.existsByPhone</code> (<code>409 PHONE_ALREADY_IN_USE</code>), checks <code>phone:otp:resend:{userId}</code> (<code>429 RATE_LIMIT_EXCEEDED</code>), stores <code>phone:otp:{userId}</code> + 60s cooldown, resets <code>phone:otp:attempt:{userId}</code>, and emails the 6-digit code.</li><li><code>verifyPhoneOtp</code>: reads <code>phone:otp:{userId}</code> (<code>400 OTP_INVALID</code> if expired/absent), increments <code>phone:otp:attempt:{userId}</code> on mismatch (5th failure deletes OTP + counter -&gt; <code>400 OTP_TOO_MANY_ATTEMPTS</code>), re-checks <code>existsByPhone</code> against concurrent claims (<code>409 PHONE_ALREADY_IN_USE</code>), saves <code>user.phone</code>, and deletes Redis OTP keys.</li></ul></li></ol><h2 id="_4-security-boundary-isolation" tabindex="-1">4. Security &amp; Boundary Isolation <a class="header-anchor" href="#_4-security-boundary-isolation" aria-label="Permalink to &quot;4. Security &amp; Boundary Isolation&quot;">​</a></h2><ul><li><strong>Strict Scope Separation:</strong> 2FA uses RFC 6238 TOTP (<code>FR 3.2.7</code>), Password Reset uses Redis link tokens (<code>FR 3.2.4</code>), and Deactivate OTP (<code>otp:deactivate:{userId}</code>) is isolated in <code>FR 3.2.9</code> — codes from one flow can never satisfy another.</li></ul><h2 id="endpoint-authorization-error-mapping-matrix" tabindex="-1">Endpoint, Authorization &amp; Error Mapping Matrix <a class="header-anchor" href="#endpoint-authorization-error-mapping-matrix" aria-label="Permalink to &quot;Endpoint, Authorization &amp; Error Mapping Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Aspect</th><th style="text-align:left;">Specification</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR / Feature</strong></td><td style="text-align:left;"><code>FR 3.2.6</code> — OTP Verification</td></tr><tr><td style="text-align:left;"><strong>HTTP / WS Endpoints</strong></td><td style="text-align:left;"><code>POST /api/v1/auth/verify-otp · POST /api/v1/auth/resend-otp · POST /api/v1/auth/link/phone · POST /api/v1/auth/verify-phone-otp</code></td></tr><tr><td style="text-align:left;"><strong>Authorized Canonical Roles</strong></td><td style="text-align:left;"><code>Guest, Owner, Manager, Creator, Client, Admin</code></td></tr><tr><td style="text-align:left;"><strong>Controller -&gt; Service</strong></td><td style="text-align:left;"><code>AuthController</code> -&gt; <code>AuthServiceImpl, MailService</code></td></tr><tr><td style="text-align:left;"><strong>Persistence / Cache Targets</strong></td><td style="text-align:left;">PostgreSQL <code>users</code>; Redis <code>otp:attempt:{email}</code>, <code>otp:resend:{email}</code>, <code>phone:otp:{userId}</code>, <code>phone:otp:attempt:{userId}</code>, <code>phone:otp:resend:{userId}</code></td></tr><tr><td style="text-align:left;"><strong>Business Rule Invariants</strong></td><td style="text-align:left;"><code>BR-03, BR-04</code></td></tr><tr><td style="text-align:left;"><strong>Error Code Contract</strong></td><td style="text-align:left;"><code>400 OTP_INVALID</code> / <code>OTP_TOO_MANY_ATTEMPTS</code> / <code>INVALID_PHONE</code>, <code>409 PHONE_ALREADY_IN_USE</code>, <code>429 RATE_LIMIT_EXCEEDED</code></td></tr></tbody></table><h2 id="frontend-cache-i18n-theme-architecture" tabindex="-1">Frontend Cache, i18n &amp; Theme Architecture <a class="header-anchor" href="#frontend-cache-i18n-theme-architecture" aria-label="Permalink to &quot;Frontend Cache, i18n &amp; Theme Architecture&quot;">​</a></h2><ul><li><strong>Web State &amp; Query Management (<code>brandhub-web</code>):</strong><ul><li>Components &amp; Hooks: <code>src/pages/auth/VerifyOtpPage.tsx</code>, <code>src/pages/profile/components/LinkPhoneModal.tsx</code>, <code>src/services/authService.ts</code>.</li><li>Query Keys &amp; Cache Invalidation: Scoped by authenticated <code>userId</code>, <code>agencyId</code>, or <code>workspaceId</code> so switching tenants or logging out never leaks cached records across boundaries.</li><li>Conflict &amp; Error Recovery: Preserves in-progress user form state on <code>400</code>/<code>409</code> responses, disables duplicate in-flight submissions, and never falls back to hardcoded mock data.</li></ul></li><li><strong>Mobile Parity (<code>brandhub-mobile-app</code>):</strong><ul><li>Screens &amp; Services: <code>app/(auth)/verify-otp.tsx</code>, <code>src/screens/settings/AccountSettingsScreen.tsx</code>.</li><li>Uses shared REST/WS contract, <code>expo-secure-store</code> Bearer token injection, and mobile <code>workspaceStore</code> / <code>authStore</code> synchronization.</li></ul></li><li><strong>Localization &amp; Theme Standards:</strong><ul><li>Key-parallel Vietnamese (<code>vi</code>) and English (<code>en</code>) locale entries under <code>auth.verifyOtp.* / profile.linkPhone.*</code> with zero hardcoded strings.</li><li>Semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useTheme()</code> semantic tokens on Mobile verified across Light and Dark modes.</li></ul></li><li><strong>Observability &amp; Audit Correlation:</strong><ul><li>Propagates <code>X-Request-Id</code> from <code>brandhub-api-gateway</code> into <code>ApiResponse.requestId</code> and structured backend logs / <code>audit_logs</code> where security-sensitive mutations occur.</li></ul></li><li><strong>BA &amp; Module Traceability:</strong> <a href="./../../../../ba/02-authentication-profile.html">BA Domain Spec</a> · <a href="./../../../../ba/README.html">BA Overview</a> · <a href="./../../../modules/README.html">Module Specs Index</a>.</li></ul>',16)])])}const g=t(c,[["render",n]]);export{u as __pageData,g as default};
